# Majority voting hypothesis
# If majority of neighbors have same color, keep that color
# Otherwise, use original color or iterate

def majority_vote_kernel(grid, kernel=3):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            # Count occurrences of each color in neighborhood
            color_counts = {2: 0, 5: 0}

            for dr in range(-(kernel-1), kernel):
                for dc in range(-(kernel-1), kernel):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        color_counts[grid[nr][nc]] += 1

            # Use majority color
            majority_color = max(color_counts, key=color_counts.get)
            result[r][c] = majority_color

    return result

