# Try another edge detection hypothesis
# Edges (cells adjacent to different color) become 2, others keep original

def edge_detection_2(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            is_edge = False
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != grid[r][c]:
                        is_edge = True
                        break

            if is_edge:
                result[r][c] = 2  # Edge becomes 2
            else:
                result[r][c] = grid[r][c]  # Keep original

    return result

