# Let me try a different transform
# Hypothesis: For each cell, count neighbors of the same color.
# If |neighbors_same - 4| is small (border), put 5, else keep original

def neighbor_count_transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            same_neighbors = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == grid[r][c]:
                        same_neighbors += 1

            # If more than 2 same neighbors (not on border), keep original
            # Otherwise (0-2 same neighbors), mark as 5
            if same_neighbors <= 2:
                result[r][c] = 5
            else:
                result[r][c] = grid[r][c]

    return result

